package com.ecommerce.servlet;
import com.ecommerce.model.*; import com.ecommerce.service.ProductService; import jakarta.servlet.*; import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import java.io.IOException; import java.math.BigDecimal;
@WebServlet("/admin/products") public class AdminProductServlet extends HttpServlet { private final ProductService s=new ProductService(); protected void doGet(HttpServletRequest r,HttpServletResponse p)throws ServletException,IOException{try{User u=(User)r.getSession().getAttribute("user");if(u==null||!"ADMIN".equals(u.getRole())){p.sendError(403);return;}r.setAttribute("products",s.list(null));r.getRequestDispatcher("/WEB-INF/views/admin-products.jsp").forward(r,p);}catch(Exception e){throw new ServletException(e);}} protected void doPost(HttpServletRequest r,HttpServletResponse p)throws ServletException,IOException{User current=(User)r.getSession().getAttribute("user");if(current==null||!"ADMIN".equals(current.getRole())){p.sendError(403);return;}try{String action=r.getParameter("action");if("delete".equals(action))s.delete(Integer.parseInt(r.getParameter("id")));else{s.add(new Product(0,r.getParameter("name"),r.getParameter("description"),new BigDecimal(r.getParameter("price")),Integer.parseInt(r.getParameter("stock")),r.getParameter("category"),r.getParameter("imageUrl")));}p.sendRedirect(r.getContextPath()+"/admin/products");}catch(Exception e){throw new ServletException(e);}} }
